import { test, expect } from '@playwright/test';

test.describe('PayPal Payment Method Selection', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should successfully select PayPal as payment method and proceed to payment page', async ({ page }) => {
    // Verify PayPal button is visible
    const paypalButton = page.getByRole('button', { name: /paypal/i });
    await expect(paypalButton).toBeVisible();

    // Click PayPal button
    await paypalButton.click();

    // Verify PayPal payment method is selected
    const paypalMethod = page.getByRole('heading', { name: /PayPal/i });
    await expect(paypalMethod).toBeVisible();

    // Verify PayPal details are displayed
    const paypalDetails = page.getByText(/PayPal/i);
    await expect(paypalDetails).toBeVisible();

    // Verify payment form is visible
    const paymentForm = page.getByRole('form', { name: /payment/i });
    await expect(paymentForm).toBeVisible();

    // Verify PayPal button is disabled (should not be clicked twice)
    await expect(paypalButton).toBeDisabled();

    // Verify success message appears
    const successMessage = page.getByText(/Payment successful/i);
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to payment page
    const paymentPage = page.getByRole('main', { name: /payment/i });
    await expect(paymentPage).toBeVisible();
  });

  test('should handle PayPal payment failure and display error message', async ({ page }) => {
    // Mock PayPal API response to simulate failure
    await page.route('**/api/paypal/payment', (route) => {
      route.abort('failed');
    });

    // Verify PayPal button is visible
    const paypalButton = page.getByRole('button', { name: /paypal/i });
    await expect(paypalButton).toBeVisible();

    // Click PayPal button
    await paypalButton.click();

    // Verify PayPal payment method is selected
    const paypalMethod = page.getByRole('heading', { name: /PayPal/i });
    await expect(paypalMethod).toBeVisible();

    // Verify PayPal details are displayed
    const paypalDetails = page.getByText(/PayPal/i);
    await expect(paypalDetails).toBeVisible();

    // Verify payment form is visible
    const paymentForm = page.getByRole('form', { name: /payment/i });
    await expect(paymentForm).toBeVisible();

    // Verify PayPal button is disabled (should not be clicked twice)
    await expect(paypalButton).toBeDisabled();

    // Verify error message appears
    const errorMessage = page.getByText(/Payment failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is redirected to error page
    const errorPage = page.getByRole('main', { name: /error/i });
    await expect(errorPage).toBeVisible();
  });
});
